// ToolCall is one tool invocation observed in a transcript. Agents emit
// these via WalkToolCalls in their native tool name space (e.g. "Bash",
// "Edit" for Claude Code; "apply_patch", "function_call" for Codex).
// Activity-layer categorization happens downstream.
type ToolCall struct {
	Name        string    // agent-native tool name
	BashCommand string    // shell command string when Name == "Bash"; empty otherwise
	Timestamp   time.Time // wall-clock time the tool was invoked
}

// ToolCallWalker walks a transcript and returns every tool invocation in
// chronological order. Agents whose transcripts do not contain tool calls
// (e.g. Cursor) return (nil, nil); callers treat that as "no data" rather
// than failure. This sits alongside TranscriptAnalyzer rather than
// extending it so agents with only partial transcript support (Cursor
// can ExtractPrompts but not WalkToolCalls) can opt in independently.
type ToolCallWalker interface {
	Agent

	// WalkToolCalls reads the transcript at path and returns all tool
	// calls in order. An empty or missing file yields no error and no
	// calls.
	WalkToolCalls(path string) ([]ToolCall, error)
