// ExtractToolCalls is the per-agent strategy: given one raw JSONL line,
// return any tool calls found on it. Return nil for lines with no tool calls
// or lines that fail to parse — the walk continues.
//
// The slice returned must not retain references to the input buffer; the
// scanner reuses it on the next call.
type ExtractToolCalls func(line []byte) []ToolCall

// WalkJSONLTranscript opens a JSONL transcript at path and applies extract
// to each line, collecting all tool calls. Empty path and missing file both
// return (nil, nil) so callers can treat absence as "no data" without
// branching on os.IsNotExist.
//
// The 16 MiB per-line buffer accommodates Claude Code tool_result payloads,
// which can be large.
func WalkJSONLTranscript(path string, extract ExtractToolCalls) ([]ToolCall, error) {
	if path == "" {
		return nil, nil
	}
	f, err := os.Open(path) //nolint:gosec // path comes from session state written by the CLI
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil, nil
		}
		return nil, fmt.Errorf("open transcript: %w", err)
	}
	defer f.Close()

	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 1<<20), 1<<24)

	var calls []ToolCall
	for scanner.Scan() {
		calls = append(calls, extract(scanner.Bytes())...)
	}
	if err := scanner.Err(); err != nil {
		return calls, fmt.Errorf("scan transcript: %w", err)
	}
	return calls, nil
}

