// ToolCall per tool_use block. Missing or empty files yield (nil, nil)
// so activity-layer callers can treat absence as "no data" without
// branching on os.IsNotExist.
func (c *ClaudeCodeAgent) WalkToolCalls(path string) ([]agent.ToolCall, error) {
	if path == "" {
		return nil, nil
	}
	f, err := os.Open(path) //nolint:gosec // path comes from session state written by the CLI
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil, nil
		}
		return nil, fmt.Errorf("open transcript: %w", err)
	}
	defer f.Close()

	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 1<<20), 1<<24) // 16 MiB per line — tool_result payloads can be large

	type lineShape struct {
		Type      string    `json:"type"`
		Timestamp time.Time `json:"timestamp"`
		Message   struct {
			Content []struct {
				Type  string          `json:"type"`
				Name  string          `json:"name,omitempty"`
				Input json.RawMessage `json:"input,omitempty"`
			} `json:"content"`
		} `json:"message"`
	}

	var calls []agent.ToolCall
	for scanner.Scan() {
		var l lineShape
		if err := json.Unmarshal(scanner.Bytes(), &l); err != nil {
			continue
		}
		for _, block := range l.Message.Content {
			if block.Type != "tool_use" {
				continue
			}
			calls = append(calls, agent.ToolCall{
				Name:        block.Name,
				BashCommand: bashCommandFromInput(block.Input),
				Timestamp:   l.Timestamp,
			})
