253			// Skip if already a string
254			var strContent string
255			if json.Unmarshal(contentRaw, &strContent) == nil {
256				continue
257			}
258	
259			// Try to convert array of {"text":"..."} to a plain string
260			var parts []struct {
261				Text string `json:"text"`
262			}
263			if json.Unmarshal(contentRaw, &parts) != nil {
264				continue
265			}
266	
267			var texts []string
268			for _, p := range parts {
269				if p.Text != "" {
270					texts = append(texts, p.Text)
271				}
272			}
273			joined := strings.Join(texts, "\n")
274			strBytes, err := json.Marshal(joined)
275			if err != nil {
276				continue
277			}
278			msg["content"] = strBytes
279			rewritten, err := json.Marshal(msg)
280			if err != nil {
281				continue
282			}
283			messages[i] = rewritten
284			changed = true
285		}
286	
287		if !changed {
288			return data, nil
289		}
290	
291		rewrittenMessages, err := json.Marshal(messages)
292		if err != nil {
293			return nil, fmt.Errorf("failed to re-serialize messages: %w", err)
294		}
295		raw["messages"] = rewrittenMessages
296	
297		result, err := json.MarshalIndent(raw, "", "  ")
298		if err != nil {
299			return nil, fmt.Errorf("failed to re-serialize transcript: %w", err)
300		}
301		return result, nil
302	}
