304	// SliceFromMessage returns a Gemini transcript scoped to messages starting from
305	// startMessageIndex. This is the Gemini equivalent of transcript.SliceFromLine —
306	// for Gemini's single JSON blob, scoping is done by message index rather than line offset.
307	// Returns the original data if startMessageIndex <= 0.
308	// Returns nil, nil if startMessageIndex exceeds the number of messages.
309	func SliceFromMessage(data []byte, startMessageIndex int) ([]byte, error) {
