package geminicli

import (
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// Compile-time assertion that GeminiCLIAgent satisfies ToolCallWalker.
var _ agent.ToolCallWalker = (*GeminiCLIAgent)(nil)

// WalkToolCalls reads Gemini CLI's JSON transcript and returns one ToolCall
// per toolCalls entry across all messages. Unlike Claude Code and Codex,
// Gemini sessions are stored as a single JSON blob rather than JSONL, so this
// walker reads the whole file instead of going through agent.WalkJSONLTranscript.
func (a *GeminiCLIAgent) WalkToolCalls(path string) ([]agent.ToolCall, error) {
	if path == "" {
		return nil, nil
	}
	data, err := os.ReadFile(path) //nolint:gosec // path comes from session state written by the CLI
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil, nil
		}
		return nil, fmt.Errorf("read transcript: %w", err)
	}
	if len(data) == 0 {
		return nil, nil
	}

	// Local parse shape: GeminiToolCall in transcript.go intentionally omits
	// the per-call timestamp field (see the NormalizeTranscript comment about
	// keeping GeminiMessage narrow), so define a minimal shape here instead of
	// mutating the shared type.
	var t struct {
		Messages []struct {
			ToolCalls []struct {
				Name      string          `json:"name"`
				Args      json.RawMessage `json:"args,omitempty"`
				Timestamp time.Time       `json:"timestamp"`
			} `json:"toolCalls,omitempty"`
		} `json:"messages"`
	}
	if err := json.Unmarshal(data, &t); err != nil {
		return nil, fmt.Errorf("parse transcript: %w", err)
	}

	var calls []agent.ToolCall
	for _, msg := range t.Messages {
		for _, tc := range msg.ToolCalls {
			calls = append(calls, agent.ToolCall{
				Name:        tc.Name,
				BashCommand: bashCommandFromArgs(tc.Name, tc.Args),
				Timestamp:   tc.Timestamp,
			})
		}
	}
	return calls, nil
}

// bashCommandFromArgs extracts the shell command string from the args JSON
// for run_shell_command, Gemini's equivalent of Claude Code's Bash tool.
// Gemini uses {"command": "..."}.
const toolNameRunShell = "run_shell_command"

func bashCommandFromArgs(name string, raw json.RawMessage) string {
	if name != toolNameRunShell {
		return ""
	}
	if len(raw) == 0 {
		return ""
	}
	var v struct {
		Command string `json:"command,omitempty"`
	}
	if err := json.Unmarshal(raw, &v); err != nil {
		return ""
	}
	return v.Command
}

