package geminicli

import (
	"os"
	"path/filepath"
	"testing"
	"time"
)

const geminiWalkFixture = `{
  "sessionId": "s",
  "messages": [
    {"type": "user", "content": "fix it"},
    {"type": "gemini", "timestamp": "2026-04-15T10:00:00Z", "toolCalls": [
      {"id": "t1", "name": "read_file", "timestamp": "2026-04-15T10:00:05Z", "args": {"file_path": "foo.go"}},
      {"id": "t2", "name": "run_shell_command", "timestamp": "2026-04-15T10:00:10Z", "args": {"command": "ls -la"}}
    ]},
    {"type": "gemini", "timestamp": "2026-04-15T10:00:20Z", "toolCalls": [
      {"id": "t3", "name": "write_file", "timestamp": "2026-04-15T10:00:15Z", "args": {"file_path": "foo.go", "content": "x"}}
    ]}
  ]
}`

func TestWalkToolCalls_GeminiBasicShape(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	p := filepath.Join(dir, "s.json")
	if err := os.WriteFile(p, []byte(geminiWalkFixture), 0o600); err != nil {
		t.Fatal(err)
	}
	calls, err := (&GeminiCLIAgent{}).WalkToolCalls(p)
	if err != nil {
		t.Fatal(err)
	}
	if len(calls) != 3 {
		t.Fatalf("expected 3 calls, got %d: %+v", len(calls), calls)
	}
	if calls[0].Name != "read_file" || calls[0].BashCommand != "" {
		t.Errorf("calls[0] = %+v", calls[0])
	}
	if calls[1].Name != "run_shell_command" || calls[1].BashCommand != "ls -la" {
		t.Errorf("calls[1] = %+v", calls[1])
	}
	if calls[2].Name != "write_file" || calls[2].BashCommand != "" {
		t.Errorf("calls[2] = %+v", calls[2])
	}
}

func TestWalkToolCalls_GeminiTimestamps(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	p := filepath.Join(dir, "s.json")
	if err := os.WriteFile(p, []byte(geminiWalkFixture), 0o600); err != nil {
		t.Fatal(err)
	}
	calls, err := (&GeminiCLIAgent{}).WalkToolCalls(p)
	if err != nil {
		t.Fatal(err)
	}
	want, err := time.Parse(time.RFC3339, "2026-04-15T10:00:05Z")
	if err != nil {
		t.Fatal(err)
	}
	if !calls[0].Timestamp.Equal(want) {
		t.Errorf("calls[0].Timestamp = %v, want %v", calls[0].Timestamp, want)
	}
}

func TestWalkToolCalls_GeminiEmptyFile(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	p := filepath.Join(dir, "empty.json")
	if err := os.WriteFile(p, nil, 0o600); err != nil {
		t.Fatal(err)
	}
	calls, err := (&GeminiCLIAgent{}).WalkToolCalls(p)
	if err != nil {
		t.Fatal(err)
	}
	if len(calls) != 0 {
		t.Errorf("expected 0 calls, got %d", len(calls))
	}
}

func TestWalkToolCalls_GeminiMissingFile(t *testing.T) {
	t.Parallel()
	calls, err := (&GeminiCLIAgent{}).WalkToolCalls("/nonexistent/session.json")
	if err != nil {
